{
  "queries": [
    {
      "doc_id": "MM-P1-L2-IH02",
      "query": "For the Ring Rolling induction billet heater #2 maintenance manual: list all electrical and thermal hazards identified, required PPE for maintenance technicians, and the lockout/tagout steps specific to the induction heater circuits."
    },
    {
      "doc_id": "SOP-P2-L4-02",
      "query": "During Product changeover on the Heat Treat line, what confined-space, thermal, and chemical exposure controls are mandated? Include required PPE and any isolation/lockout steps before tooling or furnace access."
    },
    {
      "doc_id": "MM-P1-L4-CN01-S2",
      "query": "For the CNC turning center #1 fastener inspection and torque procedure: what hazards are called out for technicians (sharp edges, chip ejection, rotating parts), what PPE is specified, and does the manual require LOTO before accessing spindle or tooling?"
    },
    {
      "doc_id": "MM-P3-L2-SB01",
      "query": "Maintenance manual for Ring Rolling shot blast cabinet #1: summarize blast media and airborne particulate hazards, respiratory protection requirements, hearing protection, and the accepted lockout/isolation methods for the blast unit prior to internal maintenance."
    },
    {
      "doc_id": "SOP-P2-L3-02",
      "query": "For Product changeover on the Machining line: what specific hazard controls and PPE are required when swapping fixtures or tooling? Confirm steps to de-energize and secure rotating equipment and any verification/communication steps for handover."
    },
    {
      "doc_id": "SOP-P3-L3-05",
      "query": "Planned shutdown — Machining line: what isolation and LOTO procedures are prescribed for multi-system shutdowns, and what additional PPE or monitoring (e.g., lockbox, verification of zero energy) is required for maintenance crews?"
    },
    {
      "doc_id": "SB-1029",
      "query": "Safety bulletin on noise exposure: what controls and PPE does the bulletin recommend for high-noise areas, and are there action thresholds or follow-up requirements for engineering controls or audiometric testing?"
    },
    {
      "doc_id": "SOP-P3-L1-04",
      "query": "Shift handover — Hot Forge line: what hazard communication items must outgoing staff convey about hot work, suspended loads, and recent repairs? Are any temporary controls or specific PPE needs to be passed between shifts?"
    },
    {
      "doc_id": "MM-P1-L4-HP02",
      "query": "Maintenance manual for Heat Treat hydraulic forging press #2: identify mechanical pinch, stored energy, and hydraulic fluid hazards; state required PPE for maintenance; and detail the hydraulic-specific lockout/isolation steps before platen removal."
    },
    {
      "doc_id": "SOP-P1-L3-02",
      "query": "Product changeover — Machining line (alternate document): compare the PPE and LOTO requirements here to SOP-P2-L3-02 and note any differences in hazard controls when changing over high-speed spindles."
    },
    {
      "doc_id": "SB-1047",
      "query": "Safety bulletin: arc flash at the induction power cabinet — what work restrictions, PPE categories, and verification steps after an arc flash event are recommended? Include any follow-up investigation or remediation actions required."
    },
    {
      "doc_id": "SB-1009",
      "query": "Safety bulletin on hot metal and scale ejection: what engineering or administrative controls are recommended to reduce ejection risk, what PPE (face, body) is mandated in affected zones, and are there exclusion distances defined?"
    },
    {
      "doc_id": "SOP-P1-L4-04",
      "query": "Shift handover — Heat Treat line: what specific hazard briefings are required about furnace status, recent maintenance, and materials in process? Does the SOP require confirmation of isolation/LOTO for items left for maintenance?"
    },
    {
      "doc_id": "MM-P1-L1-RR01",
      "query": "Maintenance manual for Hot Forge radial ring rolling mill #1: enumerate mechanical and thermal hazards during maintenance, required PPE, and the prescribed lockout sequence for the rolling mill drive and hydraulic systems."
    },
    {
      "doc_id": "SOP-P1-L1-05",
      "query": "Planned shutdown — Hot Forge line: what are the documented steps for isolating thermal, electrical, and mechanical energy sources during a planned outage, and what additional PPE or atmospheric monitoring is required for furnace entry?"
    },
    {
      "doc_id": "SB-1033",
      "query": "Safety bulletin regarding airborne dust from blasting: what respiratory protection levels and controls are recommended, and are there housekeeping or HEPA ventilation follow-ups mandated after blasting operations?"
    },
    {
      "doc_id": "MM-P3-L1-IH03",
      "query": "Maintenance manual for Hot Forge induction billet heater #3: identify unique induction-related hazards (e.g., stray electromagnetic fields, residual heat), PPE for service, and required LOTO/isolation for high-voltage and cooling systems."
    },
    {
      "doc_id": "SOP-P2-L1-02",
      "query": "Product changeover — Hot Forge line: what controls are required to manage hot surfaces, residual heat, and scale during changeover? Detail PPE expectations and any mandatory isolation steps before hands-on tasks."
    },
    {
      "doc_id": "MM-P2-L3-HT02",
      "query": "Maintenance manual for Machining heat treat furnace #2: what chemical, thermal, and electrical hazards are listed; what PPE is required for maintenance; and what are the furnace-specific LOTO, purge, or cooldown verification steps?"
    },
    {
      "doc_id": "MM-P2-L1-RR01",
      "query": "Maintenance manual for Hot Forge radial ring rolling mill #1 (alternate): are there any differences from MM-P1-L1-RR01 in required PPE, lockout sequence, or noted hazards—specifically for hydraulic vs. electric drive components?"
    }
  ]
}
